package com.bplus.share;
import android.app.*;import android.media.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Lazy local audio playback. No source setup on UI draw; only the active note polls progress. */
public final class VoicePlayer{
 private static final ExecutorService io=Executors.newSingleThreadExecutor();
 private static final Map<String,Integer> durations=Collections.synchronizedMap(new HashMap<>());
 private static final WeakHashMap<Activity,ArrayList<Session>> sessions=new WeakHashMap<>();
 private static Session playing;
 public static void release(Activity a){ArrayList<Session> list=sessions.remove(a);if(list!=null)for(Session s:list)s.release();}
 static String time(int ms){return VoiceTime.time(ms);}
 private static void exclusive(Session next){if(playing!=null&&playing!=next)playing.pause();playing=next;}
 public static View view(Activity a,Uri uri,int ink){LinearLayout col=Ui.col(a),row=Ui.row(a);row.setGravity(Gravity.CENTER_VERTICAL);TextView play=Ui.t(a,"▶",22,ink,App.cairoB);play.setGravity(Gravity.CENTER);play.setContentDescription(a.getString(R.string.voice_play));row.addView(play,Ui.lp(Ui.dp(a,40),Ui.dp(a,48)));FrameLayout track=new FrameLayout(a);SeekBar seek=new SeekBar(a);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(ink));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(ink));FrameLayout.LayoutParams line=new FrameLayout.LayoutParams(-1,Ui.dp(a,32),Gravity.CENTER_VERTICAL);track.addView(seek,line);TextView clock=Ui.t(a,VoiceTime.label(0,-1),10.5f,ink,App.cairoSB);clock.setSingleLine(true);clock.setGravity(Gravity.CENTER);clock.setTextDirection(View.TEXT_DIRECTION_LTR);clock.setEllipsize(android.text.TextUtils.TruncateAt.END);FrameLayout.LayoutParams label=new FrameLayout.LayoutParams(-1,Ui.dp(a,15),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);track.addView(clock,label);row.addView(track,new LinearLayout.LayoutParams(0,Ui.dp(a,50),1f));col.addView(row,Ui.lp(Ui.dp(a,226),Ui.dp(a,50)));Session session=new Session(a,uri,play,seek,clock);ArrayList<Session> list=sessions.get(a);if(list==null){list=new ArrayList<>();sessions.put(a,list);}list.add(session);session.metadata();play.setOnClickListener(v->session.toggle());seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int progress,boolean user){if(user)session.seek(progress);}public void onStartTrackingTouch(SeekBar s){session.dragging=true;}public void onStopTrackingTouch(SeekBar s){session.dragging=false;}});return col;}
 private static final class Session{
 final Activity a;final Uri uri;final TextView play,clock;final SeekBar seek;final Handler ui=new Handler(Looper.getMainLooper());final Object lock=new Object();MediaPlayer player;volatile boolean released;boolean ready,loading,running,dragging,wantsPlay;int duration,lastSecond=-1;
 Session(Activity a,Uri uri,TextView play,SeekBar seek,TextView clock){this.a=a;this.uri=uri;this.play=play;this.seek=seek;this.clock=clock;}
 void metadata(){Integer cached=durations.get(uri.toString());if(cached!=null){duration=cached;clock.setText(VoiceTime.label(0,duration));return;}io.execute(()->{if(released)return;int length=-1;MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(a,uri);String value=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(value!=null)length=Integer.parseInt(value);}catch(Exception ignored){}finally{try{r.release();}catch(Exception ignored){}}final int total=length;if(total>=0)durations.put(uri.toString(),total);ui.post(()->{if(!released&&!ready){duration=Math.max(0,total);clock.setText(VoiceTime.label(0,total));}});});}
 void toggle(){if(released)return;if(running){pause();return;}exclusive(this);wantsPlay=true;if(ready){start();return;}if(loading)return;loading=true;play.setText("…");player=new MediaPlayer();player.setOnPreparedListener(p->{if(released)return;loading=false;ready=true;duration=p.getDuration();durations.put(uri.toString(),duration);seek.setMax(duration);clock.setText(VoiceTime.label(0,duration));if(wantsPlay)start();else play.setText("▶");});player.setOnCompletionListener(p->{running=false;ui.removeCallbacks(tick);play.setText("▶");seek.setProgress(duration);clock.setText(VoiceTime.label(duration,duration));});player.setOnErrorListener((p,w,e)->{failed();return true;});io.execute(()->{synchronized(lock){if(released)return;try{player.setDataSource(a,uri);player.prepareAsync();}catch(Exception e){ui.post(this::failed);}}});}
 void start(){if(released||!ready)return;try{exclusive(this);player.start();lastSecond=-1;running=true;play.setText("❚❚");ui.removeCallbacks(tick);ui.post(tick);}catch(Exception e){failed();}}
 void pause(){wantsPlay=false;running=false;ui.removeCallbacks(tick);try{if(ready&&player!=null)player.pause();}catch(Exception ignored){}play.setText("▶");}
 void seek(int position){if(!ready||released)return;try{player.seekTo(position);clock.setText(VoiceTime.label(position,duration));lastSecond=-1;}catch(Exception ignored){}}
 final Runnable tick=new Runnable(){public void run(){if(released||!running)return;try{int position=player.getCurrentPosition();if(!dragging)seek.setProgress(position);int second=position/1000;if(second!=lastSecond){lastSecond=second;clock.setText(VoiceTime.label(position,duration));}ui.postDelayed(this,80);}catch(Exception e){failed();}}};
 void failed(){if(released)return;running=false;loading=false;ui.removeCallbacks(tick);clock.setText(R.string.voice_play_failed);play.setText("▶");}
 void release(){released=true;running=false;ui.removeCallbacksAndMessages(null);if(playing==this)playing=null;io.execute(()->{synchronized(lock){if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}}});}
 }
}
